-- Generated by Claude Code — Geräte-Token dem aktuell angemeldeten Konto
-- zuordnen. Ein Gerät wechselt z. B. von der anonymen Start-Session zum
-- echten Konto; per RLS dürfte das neue Konto die fremde Zeile nicht
-- übernehmen, Pushes gingen sonst weiter an die alte anonyme Session.
create or replace function register_push_token(p_token text, p_platform text)
returns void
language plpgsql
security definer
set search_path = public
as $$
begin
  if auth.uid() is null then raise exception 'Nicht angemeldet.'; end if;
  if p_token is null or length(p_token) < 10 or length(p_token) > 400 then raise exception 'Ungültiges Token.'; end if;
  insert into push_tokens (user_id, token, platform)
  values (auth.uid(), p_token, left(coalesce(p_platform, 'ios'), 20))
  on conflict (token) do update set user_id = excluded.user_id, platform = excluded.platform, created_at = now();
end;
$$;

revoke all on function register_push_token(text, text) from public, anon;
grant execute on function register_push_token(text, text) to authenticated;
